carrier_event = {
	id = nomads.1
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		NOR = {
			is_planet_class = pc_ark
			has_carrier_flag = nomad_recently_settled_flag
		}
		from = { # Nomads should *never* have planets
			is_nomadic = yes
			has_policy_flag = nomad_total_war_subject
		}
	}

	immediate = {
		if = { # We split the check for attacker war and defender war into two different if's just to make scripting easier.
			limit = { 	exists = fromfrom 	from = { 		is_at_war_with = fromfrom 		any_war = { 			any_attacker = { 				is_same_value = fromfrom 			} 			any_defender = { 				is_same_value = prevprev 			} 			any_defender = { 				has_claim = root.solar_system 				is_nomadic = no  			} 		} 	} } from = { 	random_war = { 		limit = { 			any_attacker = { 				is_same_value = fromfrom 			} 			any_defender = { 				is_same_value = prevprev 			} 			any_defender = { 				has_claim = root.solar_system 				is_nomadic = no  			} 		} 		ordered_defender = { 			limit = { 				is_nomadic = no 				has_claim = root.solar_system 			} 			position = 0 			order_by = value:num_claims_on_system|TARGET|root.solar_system| 			root = { 				set_owner = prev 			} 		} 	} }








		}
		else_if = {
			limit = { 	exists = fromfrom 	from = { 		is_at_war_with = fromfrom 		any_war = { 			any_defender = { 				is_same_value = fromfrom 			} 			any_attacker = { 				is_same_value = prevprev 			} 			any_attacker = { 				has_claim = root.solar_system 				is_nomadic = no  			} 		} 	} } from = { 	random_war = { 		limit = { 			any_defender = { 				is_same_value = fromfrom 			} 			any_attacker = { 				is_same_value = prevprev 			} 			any_attacker = { 				has_claim = root.solar_system 				is_nomadic = no  			} 		} 		ordered_attacker = { 			limit = { 				is_nomadic = no 				has_claim = root.solar_system 			} 			position = 0 			order_by = value:num_claims_on_system|TARGET|root.solar_system| 			root = { 				set_owner = prev 			} 		} 	} }








		}
		else_if = {
			limit = {
				exists = fromfrom
				fromfrom = {
					num_owned_planets > 0
				}
			}
			if = {
				limit = {
					from = {
						any_subject = {
							has_country_flag = nomad_vassal@fromfrom
						}
					}
				}
				from = {
					random_subject = {
						limit = {
							has_country_flag = nomad_vassal@fromfrom
						}
						save_event_target_as = nomad_vassal
						give_planet_and_system_to_rebel = {
							PLANET = root
							REBEL = event_target:nomad_vassal
							OLD_OWNER = fromfrom
						}
						nomad_vassal_join_overlord_wars_effect = yes
					}
				}
			}
			else_if = {
				limit = {
					fromfrom = { is_country_type = default }
				}
				fromfrom.capital_scope.planet = {
					create_rebels = {
						name = random
						ethos = fromfrom
						authority = fromfrom
						civics = fromfrom
						origin = origin_default
						species = fromfrom.species
						flag = random
						effect = {
							set_country_type = default
							set_country_flag = nomad_vassal@fromfrom
							establish_communications_no_message = from
							establish_communications_no_message = fromfrom
							if = {
								limit = {
									is_homicidal = yes
								}
								change_government = {
									civics = random
								}
							}
							if = {
								limit = {
									has_trait = trait_necrophage
								}
								set_origin = origin_necrophage
							}
							else_if = {
								limit = {
									has_trait = trait_void_dweller_1
								}
								set_origin = origin_void_dwellers
							}
							else_if = {
								limit = {
									has_trait = trait_void_dweller_2
								}
								set_origin = origin_void_machines
							}
							else_if = {
								limit = {
									has_trait = trait_cave_dweller
								}
								set_origin = origin_subterranean
							}
							else_if = {
								limit = {
									has_trait = trait_robot_cave_dweller
								}
								set_origin = origin_subterranean_machines
							}
							else_if = {
								limit = {
									root.owner = { has_origin = origin_tree_of_life }
									has_trait = trait_hive_mind
								}
								set_origin = origin_tree_of_life
							}

							if = {
								limit = {
									has_trait = trait_machine_unit
									root.owner = { is_individual_machine = no }
									NOT = { has_ethic = ethic_gestalt_consciousness }
								}
								shift_ethic = ethic_gestalt_consciousness
								change_government = {
									authority = auth_machine_intelligence
									civics = random
								}
							}
							else_if = {
								limit = {
									has_trait = trait_hive_mind
									NOT = { has_ethic = ethic_gestalt_consciousness }
								}
								shift_ethic = ethic_gestalt_consciousness
								change_government = {
									authority = auth_hive_mind
									civics = random
								}
							}
							save_event_target_as = nomad_vassal
							set_subject_of = {
								who = root.owner
								preset = preset_nomad_tributary
							}
							give_planet_and_system_to_rebel = {
								PLANET = root
								REBEL = event_target:nomad_vassal
								OLD_OWNER = fromfrom
							}
							nomad_vassal_join_overlord_wars_effect = yes
						}
					}
				}
			}
			else = { #If we are taking the planet from some weird non default country we create a regular vassal
				create_country= {
					name = random
					ethos = from
					authority = from
					civics = from
					remove_invalid_civics = yes # drop nomad-only civics that aren't valid for this non-nomad vassal
					origin = origin_liberated
					species = from.species
					flag = random
					effect = {
						set_country_type = default
						set_country_flag = nomad_vassal@fromfrom
						establish_communications_no_message = from
						establish_communications_no_message = fromfrom
						from = {
							every_relation = {
								establish_communications_no_message = prevprev
								add_intel_report = { #Ensuring that they know we are purging pops
									category = economy
									level = 1
									who = prevprev
								}
							}
						}
						set_policy = {
							policy = robot_pop_policy
							option = robot_pops_outlawed
							cooldown = yes
						}
						add_opinion_modifier = { modifier = opinion_liberated_us who = from }
						copy_techs_from = {
							target = from
						}
						copy_traditions_from = {
							target = from
						}
						save_event_target_as = nomad_vassal
						set_subject_of = {
							who = from
							preset = preset_nomadic_purger
						}
						random_agreement = {
							add_loyalty = 100
						}
						give_planet_and_system_to_rebel = {
							PLANET = root
							REBEL = event_target:nomad_vassal
							OLD_OWNER = fromfrom
						}
						nomad_vassal_join_overlord_wars_effect = yes
						refresh_species_rights = yes
					}
				}
			}
		}
		else_if = {
			limit = {
				exists = fromfrom
				fromfrom = {
					num_owned_planets = 0
				}
			}
			if = {
				limit = {
					fromfrom = {
						is_homicidal = no
						is_country_type = default
					}
				}
				from = {
					if = {
						limit = {
							any_subject = {
								has_country_flag = nomad_vassal@fromfrom
							}
						}
						random_subject = {
							limit = {
								has_country_flag = nomad_vassal@fromfrom
							}
							save_event_target_as = nomad_vassal
							fromfrom = {
								set_subject_of = {
									who = root.owner
									preset = preset_nomad_tributary
									allow_instant_negotiation = yes
								}
							}
							give_planet_and_system_to_rebel = {
								PLANET = root
								REBEL = fromfrom
								OLD_OWNER = event_target:nomad_vassal
							}
							every_owned_planet = {
								save_event_target_as = target_planet
								give_planet_and_system_to_rebel = {
									PLANET = event_target:target_planet
									REBEL = fromfrom
									OLD_OWNER = event_target:nomad_vassal
								}
							}
						}
					}
					else = {
						fromfrom = {
							set_subject_of = {
								who = root.owner
								preset = preset_nomad_tributary
								allow_instant_negotiation = yes
							}
						}
						root = {
							set_owner = fromfrom
						}
					}
				}
			}
			else = {
				if = {
					limit = {
						from = {
							any_subject = {
								has_country_flag = nomad_vassal@fromfrom
							}
						}
					}
					from = {
						random_subject = {
							limit = {
								has_country_flag = nomad_vassal@fromfrom
							}
							save_event_target_as = nomad_vassal
							give_planet_and_system_to_rebel = {
								PLANET = root
								REBEL = event_target:nomad_vassal
								OLD_OWNER = fromfrom
							}
							nomad_vassal_join_overlord_wars_effect = yes
						}
					}
				}

				else_if = {
					limit = {
						fromfrom = { is_country_type = default }
					}
					fromfrom.capital_scope.planet = {
						create_rebels = {
							name = random
							ethos = fromfrom
							authority = fromfrom
							civics = fromfrom
							origin = origin_default
							species = fromfrom.species
							flag = random
							effect = {
								set_country_type = default
								set_country_flag = nomad_vassal@fromfrom
								establish_communications_no_message = from
								establish_communications_no_message = fromfrom
								if = {
									limit = {
										is_homicidal = yes
									}
									change_government = {
										civics = random
									}
								}
								if = {
									limit = {
										has_trait = trait_necrophage
									}
									set_origin = origin_necrophage
								}
								else_if = {
									limit = {
										has_trait = trait_void_dweller_1
									}
									set_origin = origin_void_dwellers
								}
								else_if = {
									limit = {
										has_trait = trait_void_dweller_2
									}
									set_origin = origin_void_machines
								}
								else_if = {
									limit = {
										has_trait = trait_cave_dweller
									}
									set_origin = origin_subterranean
								}
								else_if = {
									limit = {
										has_trait = trait_robot_cave_dweller
									}
									set_origin = origin_subterranean_machines
								}
								else_if = {
									limit = {
										root.owner = { has_origin = origin_tree_of_life }
										has_trait = trait_hive_mind
									}
									set_origin = origin_tree_of_life
								}

								if = {
									limit = {
										has_trait = trait_machine_unit
										root.owner = { is_individual_machine = no }
										NOT = { has_ethic = ethic_gestalt_consciousness }
									}
									shift_ethic = ethic_gestalt_consciousness
									change_government = {
										authority = auth_machine_intelligence
										civics = random
									}
								}
								else_if = {
									limit = {
										has_trait = trait_hive_mind
										NOT = { has_ethic = ethic_gestalt_consciousness }
									}
									shift_ethic = ethic_gestalt_consciousness
									change_government = {
										authority = auth_hive_mind
										civics = random
									}
								}
								save_event_target_as = nomad_vassal
								set_subject_of = {
									who = root.owner
									preset = preset_nomad_tributary
								}
								give_planet_and_system_to_rebel = {
									PLANET = root
									REBEL = event_target:nomad_vassal
									OLD_OWNER = fromfrom
								}
								nomad_vassal_join_overlord_wars_effect = yes
							}
						}
					}
				}
				else = { #If we are taking the planet from some weird non default country we create a regular vassal
					create_country= {
						name = random
						ethos = from
						authority = from
						civics = from
						remove_invalid_civics = yes # drop nomad-only civics that aren't valid for this non-nomad vassal
						origin = origin_liberated
						species = from.species
						flag = random
						effect = {
							set_country_type = default
							set_country_flag = nomad_vassal@fromfrom
							establish_communications_no_message = from
							establish_communications_no_message = fromfrom
							from = {
								every_relation = {
									establish_communications_no_message = prevprev
									add_intel_report = { #Ensuring that they know we are purging pops
										category = economy
										level = 1
										who = prevprev
									}
								}
							}
							set_policy = {
								policy = robot_pop_policy
								option = robot_pops_outlawed
								cooldown = yes
							}
							add_opinion_modifier = { modifier = opinion_liberated_us who = from }
							copy_techs_from = {
								target = from
							}
							copy_traditions_from = {
								target = from
							}
							save_event_target_as = nomad_vassal
							set_subject_of = {
								who = from
