carrier_event = { # Purge variant
	id = nomads.5
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		NOR = {
			is_planet_class = pc_ark
			has_carrier_flag = nomad_recently_settled_flag
		}
		from = { # Nomads should *never* have planets
			is_nomadic = yes
			OR = {
				AND = {
					has_valid_civic = civic_machine_terminator
					fromfrom = {
						is_machine_empire = no
					}
				}
				has_policy_flag = nomad_total_war_purge
				has_policy_flag = nomad_total_war_displace
			}
		}
	}

	immediate = {
		if = { # We split the check for attacker war and defender war into two different if's just to make scripting easier.
			limit = { 	exists = FromFrom 	From = { 		is_at_war_with = FromFrom 		any_war = { 			any_attacker = { 				is_same_value = FromFrom 			} 			any_defender = { 				is_same_value = prevprev 			} 			any_defender = { 				has_claim = root.solar_system 				is_nomadic = no  			} 		} 	} } From = { 	random_war = { 		limit = { 			any_attacker = { 				is_same_value = FromFrom 			} 			any_defender = { 				is_same_value = prevprev 			} 			any_defender = { 				has_claim = root.solar_system 				is_nomadic = no  			} 		} 		ordered_defender = { 			limit = { 				is_nomadic = no 				has_claim = root.solar_system 			} 			position = 0 			order_by = value:num_claims_on_system|TARGET|root.solar_system| 			root = { 				set_owner = prev 			} 		} 	} }








		}
		else_if = {
			limit = { 	exists = FromFrom 	From = { 		is_at_war_with = FromFrom 		any_war = { 			any_defender = { 				is_same_value = FromFrom 			} 			any_attacker = { 				is_same_value = prevprev 			} 			any_attacker = { 				has_claim = root.solar_system 				is_nomadic = no  			} 		} 	} } From = { 	random_war = { 		limit = { 			any_defender = { 				is_same_value = FromFrom 			} 			any_attacker = { 				is_same_value = prevprev 			} 			any_attacker = { 				has_claim = root.solar_system 				is_nomadic = no  			} 		} 		ordered_attacker = { 			limit = { 				is_nomadic = no 				has_claim = root.solar_system 			} 			position = 0 			order_by = value:num_claims_on_system|TARGET|root.solar_system| 			root = { 				set_owner = prev 			} 		} 	} }








		}
		else_if = {
			limit = {
				exists = fromfrom
			}
			# Displace approach: absorb a fraction of the population before the vassal displaces the rest.
			if = {
				limit = { from = { has_policy_flag = nomad_total_war_displace } }
				nomad_assimilate_displaced_pops_effect = { NOMAD = from }
			}
			if = {
				limit = {
					from = {
						any_subject = {
							has_country_flag = nomad_vassal@fromfrom
						}
					}
				}
				from = {
					random_subject = {
						limit = {
							has_country_flag = nomad_vassal@fromfrom
						}
						save_event_target_as = nomad_vassal
						give_planet_and_system_to_rebel = {
							PLANET = root
							REBEL = event_target:nomad_vassal
							OLD_OWNER = fromfrom
						}
						nomad_vassal_join_overlord_wars_effect = yes
						refresh_species_rights = yes
					}
				}
			}
			else = {
				create_country= {
					name = random
					ethos = from
					authority = from
					civics = from
					remove_invalid_civics = yes # drop nomad-only civics that aren't valid for this non-nomad vassal
					origin = origin_nomadic_purger
					species = from.species
					flag = random
					effect = {
						set_country_type = default
						set_country_flag = nomad_vassal@fromfrom
						establish_communications_no_message = from
						establish_communications_no_message = fromfrom
						from = {
							every_relation = {
								establish_communications_no_message = prevprev
								add_intel_report = { #Ensuring that they know we are purging pops
									category = economy
									level = 1
									who = prevprev
								}
							}
						}
						set_policy = {
							policy = robot_pop_policy
							option = robot_pops_outlawed
							cooldown = yes
						}
						add_opinion_modifier = { modifier = opinion_liberated_us who = from }
						copy_techs_from = {
							target = from
						}
						copy_traditions_from = {
							target = from
						}
						save_event_target_as = nomad_vassal
						set_subject_of = {
							who = from
							preset = preset_nomadic_purger
						}
						random_agreement = {
							add_loyalty = 100
						}
						give_planet_and_system_to_rebel = {
							PLANET = root
							REBEL = event_target:nomad_vassal
							OLD_OWNER = fromfrom
						}
						nomad_vassal_join_overlord_wars_effect = yes
						refresh_species_rights = yes
					}
				}
			}
		}

		else = { #If there was no previous owner there will be no vassal
			destroy_colony = yes
		}
	}
}

