script:
event = {
	id = nomads.11
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		any_playable_country = {
			has_origin = origin_nomadic_purger
			exists = overlord
		}
	}

	immediate = {
		every_playable_country = {
			limit = {
				has_origin = origin_nomadic_purger
				exists = overlord
			}
			every_owned_colony = {
				# Nothing left to purge or assimilate: the vassal's work is done, so abandon it. The abandon step hands up
				# every remaining pop (including the assimilated ones) to the overlord in one lump sum.
				if = {
					limit = {
						has_current_purge = no
						NOT = { any_owned_pop_group = { is_being_assimilated = yes } }
					}
					nomad_purge_vassal_abandon_colony_effect = yes
				}
			}
		}
	}
