script:
carrier_event = {
	id = nomads.13
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		exists = owner
		owner = {
			has_origin = origin_nomadic_purger
			exists = overlord
		}
	}

	immediate = {
		# Colony message targets are not implemented (AUG-55014) and everything here is destroyed soon after, so
		# all values are frozen into the message at creation and the target is the purged planet, which persists.
		owner = {
			save_event_target_as = purge_vassal_country
			set_variable = { which = purge_xfer_pops  value = 0 }
			if = {
				limit = { is_variable_set = purge_resettled_pops }
				set_variable = { which = purge_xfer_pops  value = purge_resettled_pops }
			}
			set_variable = { which = purge_xfer_total  value = purge_xfer_pops }
			set_purge_xfer_resource_effect = { RESOURCE = minerals }
			set_purge_xfer_resource_effect = { RESOURCE = food }
			set_purge_xfer_resource_effect = { RESOURCE = energy }
			set_purge_xfer_resource_effect = { RESOURCE = alloys }
			set_purge_xfer_resource_effect = { RESOURCE = consumer_goods }
			set_purge_xfer_resource_effect = { RESOURCE = trade }
			set_purge_xfer_resource_effect = { RESOURCE = volatile_motes }
			set_purge_xfer_resource_effect = { RESOURCE = exotic_gases }
			set_purge_xfer_resource_effect = { RESOURCE = rare_crystals }
			set_purge_xfer_resource_effect = { RESOURCE = sr_living_metal }
			set_purge_xfer_resource_effect = { RESOURCE = sr_zro }
			set_purge_xfer_resource_effect = { RESOURCE = sr_dark_matter }
			set_purge_xfer_resource_effect = { RESOURCE = nanites }
			set_purge_xfer_resource_effect = { RESOURCE = minor_artifacts }
			set_purge_xfer_resource_effect = { RESOURCE = astral_threads }
			# Resources-only total, so the toast can line-break its resources and pops sections independently.
			set_variable = { which = purge_xfer_res_total  value = purge_xfer_total }
			subtract_variable = { which = purge_xfer_res_total  value = purge_xfer_pops }
		}
		# Created before the transfer below empties the vassal's stockpile
		owner.overlord = {
			create_message = {
				type = NOMADIC_PURGE_COMPLETE
				localization = NOMADIC_PURGE_COMPLETE_DESC
				days = 30
				target = root
				variable = {
					type = name
					localization = PLANET
					scope = root
				}
				variable = {
					type = resources
					localization = RESOURCES
					scope = event_target:purge_vassal_country
					resources = { minerals food energy alloys consumer_goods trade volatile_motes exotic_gases rare_crystals sr_living_metal sr_zro sr_dark_matter nanites minor_artifacts astral_threads }
					trigger = { event_target:purge_vassal_country = { check_variable = { which = purge_xfer_res_total  value > 0 } } }
				}
				variable = {
					type = variable
					varname = purge_xfer_pops
					localization = POPS
					scope = event_target:purge_vassal_country
					trigger = { event_target:purge_vassal_country = { check_variable = { which = purge_xfer_pops  value > 0 } } }
				}
				variable = {
					type = key
					localization = POPS_UNIT
					value = purge_xfer_unit_pops
					trigger = { event_target:purge_vassal_country = { check_variable = { which = purge_xfer_pops  value > 0 } } }
				}
				variable = {
					# " and " joins the resources and pops, but only shows when both sections are present
					type = key
					localization = AND
					value = purge_xfer_and
					trigger = {
						event_target:purge_vassal_country = {
							check_variable = { which = purge_xfer_res_total  value > 0 }
							check_variable = { which = purge_xfer_pops  value > 0 }
						}
					}
				}
				variable = {
					# Single line-break putting the gained resources/pops on their own line below the headline
					type = key
					localization = LINEBREAK
					value = purge_xfer_linestart
					trigger = { event_target:purge_vassal_country = { check_variable = { which = purge_xfer_total  value > 0 } } }
				}
				variable = {
					type = key
					localization = GAINED
					value = purge_xfer_lineend
					trigger = { event_target:purge_vassal_country = { check_variable = { which = purge_xfer_total  value > 0 } } }
				}
			}
		}
		if = {
			limit = {
				owner = { num_owned_planets <= 1 }
			}
			owner = {
				set_timed_country_flag = {
					flag = supress_country_destroyed_message
					days = 2
				}
				transfer_resources_to_empire = {
					target = overlord
					resources = { minerals food energy alloys consumer_goods trade volatile_motes exotic_gases rare_crystals sr_living_metal sr_zro sr_dark_matter nanites minor_artifacts astral_threads }
					percentage = 1.0
				}
			}
		}
		# Clear the snapshot so a later engine-removed colony cannot show this colony's pops
		owner = {
			set_variable = { which = purge_resettled_pops  value = 0 }
		}
	}
}

country_event = {
	id = nomads.15
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		is_nomadic = yes
	}

	immediate = {
		if = { # We split the check for attacker war and defender war into two different if's just to make scripting easier.
			limit = { 	exists = FromFrom 	Root = { 		is_at_war_with = FromFrom 		any_war = { 			any_defender = { 				is_same_value = FromFrom 			} 			any_attacker = { 				is_same_value = prevprev 			} 			any_attacker = { 				has_claim = from 				is_nomadic = no  			} 		} 	} } Root = { 	random_war = { 		limit = { 			any_defender = { 				is_same_value = FromFrom 			} 			any_attacker = { 				is_same_value = prevprev 			} 			any_attacker = { 				has_claim = from 				is_nomadic = no  			} 		} 		ordered_attacker = { 			limit = { 				is_nomadic = no 				has_claim = from 			} 			position = 0 			order_by = value:num_claims_on_system|TARGET|from| 			from.starbase = { 				set_owner = prev 			} 		} 	} }







		}
		else_if = {
			limit = { 	exists = FromFrom 	Root = { 		is_at_war_with = FromFrom 		any_war = { 			any_attacker = { 				is_same_value = FromFrom 			} 			any_defender = { 				is_same_value = prevprev 			} 			any_defender = { 				has_claim = from 				is_nomadic = no  			} 		} 	} } Root = { 	random_war = { 		limit = { 			any_attacker = { 				is_same_value = FromFrom 			} 			any_defender = { 				is_same_value = prevprev 			} 			any_defender = { 				has_claim = from 				is_nomadic = no  			} 		} 		ordered_defender = { 			limit = { 				is_nomadic = no 				has_claim = from 			} 			position = 0 			order_by = value:num_claims_on_system|TARGET|from| 			from.starbase = { 				set_owner = prev 			} 		} 	} }







		}
		else_if = { #If we are the Khan we give the system to our system holder
			limit = {
				has_country_flag = heir_of_the_khan_khan
				exists = event_target:marauder_country_1
			}
			event_target:marauder_country_1 = {
				from.starbase = {
					set_owner = prev
				}
			}
		}
		else_if = { #If we have a vassal we give the system to them
			limit = {
				exists = fromfrom
				any_subject = {
					has_country_flag = nomad_vassal@fromfrom
				}
			}
			random_subject = {
				limit = {
					has_country_flag = nomad_vassal@fromfrom
				}
				from.starbase = {
					set_owner = prev
				}
			}
		}
		else_if = { #If we have no vassal we give the system to the closest ally
			limit = { 	exists = FromFrom 	Root = { 		is_at_war_with = FromFrom 		any_war = { 			any_defender = { 				is_same_value = FromFrom 			} 			any_attacker = { 				is_same_value = prevprev 			} 			any_attacker = { 				is_nomadic = no  			} 		} 	} } Root = { 	random_war = { 		limit = { 			any_defender = { 				is_same_value = FromFrom 			} 			any_attacker = { 				is_same_value = prevprev 			} 			any_attacker = { 				is_nomadic = no  			} 		} 		ordered_attacker = { 			limit = { 				is_nomadic = no 			} 			position = 0 			order_by = capital_scope.solar_system.value:distance_to_target|TARGET|from|  			from.starbase = { 				set_owner = prev 			} 		} 	} }







		}
		else_if = {
			limit = { 	exists = FromFrom 	Root = { 		is_at_war_with = FromFrom 		any_war = { 			any_attacker = { 				is_same_value = FromFrom 			} 			any_defender = { 				is_same_value = prevprev 			} 			any_defender = { 				is_nomadic = no  			} 		} 	} } Root = { 	random_war = { 		limit = { 			any_attacker = { 				is_same_value = FromFrom 			} 			any_defender = { 				is_same_value = prevprev 			} 			any_defender = { 				is_nomadic = no  			} 		} 		ordered_defender = { 			limit = { 				is_nomadic = no 			} 			position = 0 			order_by = capital_scope.solar_system.value:distance_to_target|TARGET|from|  			from.starbase = { 				set_owner = prev 			} 		} 	} }







		}
		else = { #No vassal, no allies, no fleets.
			from.starbase = {
				fleet = { destroy_fleet = this }
			}
		}
	}
}

