trigger:
is_triggered_only = yes
trigger = {
		is_nomadic = yes
		has_origin = origin_forever_cruise
		OR = {
			count_issued_contracts < 3
			# Higher backlog allowed while favoring passengers or crew
			AND = {
				count_issued_contracts < 5
				cruise_favoring_side_approach = yes
			}
		}
		any_situation = {
			is_situation_type = situation_passenger_satisfaction
			OR = {
				situation_progress < 450
				situation_progress > 550
			}
		}
		NOR = {
			has_country_flag = forever_cruise_planetfall
			has_country_flag = forever_cruise_mutiny
			has_country_flag = forever_cruise_over
		}
	}

