country_event = {
	id = nomads.3105
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		fromfromfromfrom = {
			is_total_war = yes
			any_war_participant = {
				is_nomadic = yes
				# Fire on a defeated arkship OR ownership of any waystation.
				OR = {
					any_owned_fleet = {
						is_arkship_fleet = yes
						any_owned_ship = {
							is_arkship_ship = yes
							is_disabled = yes
						}
					}
					any_owned_fleet = {
						any_owned_ship = {
							is_waystation_ship = yes
						}
					}
				}
			}
		}
	}

	immediate = {
		# Resolve the on_status_quo scope chain (see header) once into readable named targets.
		fromfrom = { save_event_target_as = total_war_main_attacker }
		fromfromfrom = { save_event_target_as = total_war_main_defender }
		fromfromfromfrom = { save_event_target_as = total_war }
		event_target:total_war = {
			# Defeated nomads forfeit their disabled arkships (with colony + pops) and waystations to the opposing war leader.
			if = {
				limit = { event_target:total_war_main_attacker = { is_nomadic = yes } }
				every_defender = {
					limit = { is_nomadic = yes }
					save_event_target_as = nomad_raid_defender
					event_target:total_war_main_attacker = {
						nomad_raid_seize_ark_effect = yes
						nomad_raid_seize_disabled_waystations_effect = yes
					}
				}
			}
			if = {
				limit = { event_target:total_war_main_defender = { is_nomadic = yes } }
				every_attacker = {
					limit = { is_nomadic = yes }
					save_event_target_as = nomad_raid_defender
					event_target:total_war_main_defender = {
						nomad_raid_seize_ark_effect = yes
						nomad_raid_seize_disabled_waystations_effect = yes
					}
				}
			}
			if = {
				limit = {
					event_target:total_war_main_attacker = { is_nomadic = no }
					OR = {
						using_war_goal = { type = wg_wipe_them_out     owner = event_target:total_war_main_attacker }
						using_war_goal = { type = wg_cleansing        owner = event_target:total_war_main_attacker }
						using_war_goal = { type = wg_absorption       owner = event_target:total_war_main_attacker }
						using_war_goal = { type = wg_assimilation     owner = event_target:total_war_main_attacker }
						using_war_goal = { type = wg_machine_uprising owner = event_target:total_war_main_attacker }
					}
				}
				every_defender = {
					limit = { is_nomadic = yes }
					annihilate_captured_arks_effect = yes
				}
			}
		}
	}
}

