else_if = {
		# A Contingency Sterilization Hub scatters the shot to a random system
		limit = {
			any_system_planet = {
				is_planet_class = pc_ai
				owner = { is_country_type = ai_empire }
			}
		}
		random_system = {
			limit = {
				NOT = { is_same_value = root }
			}
			dyson_gun_apply_damage = yes
		}
		# The Contingency reports that it has hijacked our targeting (FROM = the Contingency)
		random_system_planet = {
			limit = {
				is_planet_class = pc_ai
				owner = { is_country_type = ai_empire }
			}
			owner = { from.owner = { country_event = { id = nomads.8050 } } }
		}
	}

else_if = {
		# Striking an Unbidden Dimensional Anchor only tears open a new rift, dealing no damage
		limit = {
			any_ship_in_system = { is_ship_size = dimensional_portal_ed }
		}
		create_unbidden_fleet = yes
		# The Unbidden savor the energy we just fed them (FROM = the Unbidden anchor's owner)
		random_ship_in_system = {
			limit = { is_ship_size = dimensional_portal_ed }
			owner = { from.owner = { country_event = { id = nomads.8055 } } }
		}
	}

else_if = {
		# Once struck, Cetana reflects every following shot back at the attacker's capital
		limit = {
			any_ship_in_system = { is_ship_size = synth_queen_titan }
			from.owner = { has_country_flag = dyson_gun_struck_cetana }
		}
		from.owner = {
			capital_scope = {
				solar_system = {
					dyson_gun_apply_damage = yes
				}
			}
		}
		# Cetana reproaches us as she turns the shot back on our capital (FROM = Cetana)
		event_target:synth_queen_country_global = {
			from.owner = { country_event = { id = nomads.8065 } }
		}
	}

else = {
		dyson_gun_apply_damage = yes
		# The first strike on Cetana primes her to reflect every shot to come
		if = {
			limit = {
				any_ship_in_system = { is_ship_size = synth_queen_titan }
			}
			from.owner = { set_country_flag = dyson_gun_struck_cetana }
			# Cetana voices her disappointment (FROM = Cetana)
			event_target:synth_queen_country_global = {
				from.owner = { country_event = { id = nomads.8060 } }
			}
		}
	}
if = {
			limit = {
				any_ship_in_system = { is_ship_size = synth_queen_titan }
			}
			from.owner = { set_country_flag = dyson_gun_struck_cetana }
			# Cetana voices her disappointment (FROM = Cetana)
			event_target:synth_queen_country_global = {
				from.owner = { country_event = { id = nomads.8060 } }
			}
		}

