trigger = {
		is_disabled = no
		has_hp_percentage <= 0.5
		is_waystation_ship = yes
		exists = from
		from = { exists = owner }
		OR = {
			# Disabled by an enemy during a nomad raid war
			from = {
				owner = {
					any_war = {
						# Symmetric raid: either side may disable the other side's waystations
						OR = {
							any_defender = { is_same_value = root.owner }
							any_attacker = { is_same_value = root.owner }
						}
						OR = {
							using_war_goal = {
								type = wg_nomad_raid
								owner = prev
							}
							using_war_goal = {
								type = wg_raid_contract
								owner = prev
							}
							AND = {
								is_total_war = yes
								prev = { is_nomadic = yes }
							}
						}
					}
				}
			}
			# Disabled by hostile space fauna instead of being destroyed (matching regular starbase behavior)
			from = { owner = { is_fauna_country = yes } }
		}
	}

