country_event = {
	id = nomads.9035
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		is_nomadic = yes
	}

	immediate = {
		every_owned_nonprimary_starbase = {
			limit = {
				is_waystation_starbase = yes
			}
			if = {
				limit = {
					waystation_has_remote_collection = yes
				}
				export_trigger_value_to_variable = {
					trigger = waystation_network_stockpile_used
					variable = waystation_collection_fill
				}
			}
			else = {
				export_trigger_value_to_variable = {
					trigger = used_stockpile_capacity_percentage
					variable = waystation_collection_fill
				}
			}
			solar_system = {
				set_variable = {
					which = waystation_collection_fill
					value = prev.waystation_collection_fill
				}
			}
		}
		every_owned_fleet = {
			limit = {
				is_ship_size = nomads_constructor
			}
			set_variable = {
				which = logistic_drop_off_fill
				value = 0
			}
			every_owned_ship = {
				limit = {
					is_ship_size = nomads_constructor
				}
				export_trigger_value_to_variable = {
					trigger = used_stockpile_capacity_percentage
					variable = logistic_drop_off_fill
				}
				if = {
					limit = {
						prev = {
							check_variable = {
								which = logistic_drop_off_fill
								value < prev.logistic_drop_off_fill
							}
						}
					}
					prev = {
						set_variable = {
							which = logistic_drop_off_fill
							value = prev.logistic_drop_off_fill
						}
					}
				}
			}
		}
	}
}

